// Runnable demo: three instances, one group id, each message to exactly one.
package com.bank.single.demo;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class SingleConsumerDemo {
    private static final Logger log = Logger.getLogger(SingleConsumerDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Topic topic = new Topic("transfers", 3);

        // Shared idempotency store (in prod: a DB unique constraint / Redis set)
        Set<String> processedIds = Collections.synchronizedSet(new HashSet<>());

        // THREE instances, SAME group id "transfer-processor"
        ConsumerGroupRuntime group = new ConsumerGroupRuntime("transfer-processor", topic);
        group.addInstance(new TransferProcessor("instance-A", processedIds));
        group.addInstance(new TransferProcessor("instance-B", processedIds));
        group.addInstance(new TransferProcessor("instance-C", processedIds));
        group.assign();

        // Payments service sends transfer events
        group.deliver("SAV2001", new TransferEvent("TXF-1", "SAV2001", "CUR3001", new BigDecimal("50000")));
        group.deliver("CUR3001", new TransferEvent("TXF-2", "CUR3001", "SAV2001", new BigDecimal("8000")));
        group.deliver("SAV9999", new TransferEvent("TXF-3", "SAV9999", "CUR3001", new BigDecimal("1500")));

        // Redelivery of TXF-1 after a rebalance — must be ignored (idempotent)
        log.warning(() -> "Redelivering TXF-1 after rebalance");
        group.deliver("SAV2001", new TransferEvent("TXF-1", "SAV2001", "CUR3001", new BigDecimal("50000")));
    }
}

