class Topic {
    private final String name;
    private final int partitions;
    Topic(String name, int partitions) { this.name = name; this.partitions = partitions; }
    int partitionCount() { return partitions; }
    int partitionFor(String key) { return Math.floorMod(key.hashCode(), partitions); }
    String getName() { return name; }
}

// ─── Would be in TransferProcessor.java (one running instance) ───
class TransferProcessor {
    private static final Logger log = Logger.getLogger(TransferProcessor.class.getName());
    private final String instanceId;
    private final Set<String> processedIds; // idempotency guard
    TransferProcessor(String instanceId, Set<String> processedIds) {
        this.instanceId = instanceId; this.processedIds = processedIds;
    }
    String getInstanceId() { return instanceId; }
    // @KafkaListener(topics="transfers", groupId="transfer-processor")
    void onTransfer(TransferEvent e) {
        if (!processedIds.add(e.getTransferId())) {
            log.warning(() -> "[" + instanceId + "] duplicate " + e.getTransferId()
                    + " ignored (idempotent)");
            return;
        }
        log.info(() -> "[" + instanceId + "] PROCESSED " + e
                + " — debited " + e.getFromAccount());
    }
}

// ─── Would be in ConsumerGroupRuntime.java ───
class ConsumerGroupRuntime {
    private static final Logger log = Logger.getLogger(ConsumerGroupRuntime.class.getName());
    private final String groupId;
    private final Topic topic;
    private final List<TransferProcessor> instances = new ArrayList<>();
    private final Map<Integer, TransferProcessor> owner = new HashMap<>();
    ConsumerGroupRuntime(String groupId, Topic topic) { this.groupId = groupId; this.topic = topic; }
    void addInstance(TransferProcessor p) { instances.add(p); }
    // Assign each partition to exactly ONE instance within this group
    void assign() {
        for (int p = 0; p < topic.partitionCount(); p++) {
            TransferProcessor inst = instances.get(p % instances.size());
            owner.put(p, inst);
            final int pp = p;
            log.info(() -> "[" + groupId + "] partition " + pp
                    + " -> " + inst.getInstanceId());
        }
    }
    void deliver(String key, TransferEvent e) {
        int p = topic.partitionFor(key);
        TransferProcessor inst = owner.get(p);
        log.info(() -> "DELIVER " + e.getTransferId() + " key=" + key
                + " -> partition " + p + " -> ONLY " + inst.getInstanceId());
        inst.onTransfer(e); // exactly one instance handles it
    }
}

